"use client";
import { useState } from 'react';
import Link from 'next/link';
import { visibleAdminWorkspaces } from '@/lib/admin-workspaces';

export default function AdminWorkspaceDirectory({ permissions }: { permissions: string[] | null }) {
  const [search, setSearch] = useState('');
  const groups = visibleAdminWorkspaces(permissions, search);
  const total = groups.reduce((sum, group) => sum + group.tools.length, 0);
  return <details className="group overflow-hidden rounded-2xl border border-neutral-200 bg-white">
    <summary className="flex min-h-16 cursor-pointer list-none items-center justify-between gap-4 p-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-emerald-600 sm:p-5 [&::-webkit-details-marker]:hidden">
      <span><span className="block text-[10px] font-bold uppercase tracking-widest text-emerald-700">Vos espaces de travail</span><span className="mt-1 block text-base font-bold text-neutral-950">Gérer ma boutique</span><span className="mt-1 block text-xs leading-5 text-neutral-500">Retrouvez les outils par tâche : vendre, aider, organiser et configurer.</span></span>
      <svg aria-hidden="true" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="shrink-0 text-neutral-500 transition-transform group-open:rotate-180"><path d="m6 9 6 6 6-6" /></svg>
    </summary>
    <div className="border-t border-neutral-100 p-4 sm:p-5">
      <label htmlFor="admin-workspace-search" className="block text-xs font-semibold text-neutral-600">Quel outil cherchez-vous ?</label>
      <div className="mt-2 flex items-center gap-2"><input id="admin-workspace-search" type="search" value={search} onChange={event => setSearch(event.target.value)} placeholder="Ex. livraison, retour, photos…" className="min-h-12 w-full min-w-0 rounded-xl border border-neutral-200 bg-neutral-50 px-4 text-base outline-none focus:border-emerald-600 focus:ring-2 focus:ring-emerald-100" />{search && <button type="button" onClick={() => setSearch('')} className="min-h-11 shrink-0 rounded-xl border px-3 text-xs font-semibold">Effacer</button>}</div>
      <p className="my-4 text-xs text-neutral-500" role="status">{total} outil{total !== 1 ? 's' : ''} disponible{total !== 1 ? 's' : ''} pour votre compte</p>
      {groups.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{groups.map(group => <section key={group.title} className="min-w-0 rounded-2xl border border-neutral-200 bg-[#fafbf8] p-4"><h3 className="text-sm font-bold text-emerald-950">{group.title}</h3><p className="mt-1 text-xs leading-5 text-neutral-500">{group.description}</p><ul className="mt-3 space-y-1">{group.tools.map(tool => <li key={tool.href}><Link href={tool.href} className="flex min-h-14 items-center justify-between gap-3 rounded-xl p-2 transition hover:bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600"><span className="min-w-0"><span className="block text-sm font-semibold text-neutral-800">{tool.label}</span><span className="mt-0.5 block text-xs leading-5 text-neutral-500">{tool.description}</span></span><span aria-hidden="true" className="shrink-0 text-neutral-400">↗</span></Link></li>)}</ul></section>)}</div> : <div className="rounded-xl bg-neutral-50 p-5 text-sm text-neutral-600">Aucun outil ne correspond à cette recherche. Essayez un autre mot.</div>}
    </div>
  </details>;
}
